entries[312737] = { ["name"] = "Donnerdröhnen", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde spuckt mehrere Blitze auf Gegner in der Nähe. Jeder Blitz verursacht Naturschaden, der umso größer ausfällt, je weiter das Ziel vom Einschlagspunkt entfernt ist.\nJeder Blitz springt noch zwei weitere Male auf." }
