entries[312749] = { ["name"] = "Befreiung", ["text"] = "Pakt-Fähigkeit\nWirken in 1.5 sek. 2 min Abklingzeit\nLöst Euch in reine Anima auf, was Eure Bewegungsgeschwindigkeit auf 300% erhöht, Eure Fallgeschwindigkeit verringert und Euch vorwärtsbefördert. Hält 4 Sek. lang an.\n\nVerringert den Radius, in dem Gegner Euch entdecken, deutlich." }
entries[312750] = { ["name"] = "Alptraum anziehen", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 1 min)\nDer beschworene Alptraum macht sich zu seinem Schöpfer auf, um ihn mit Macht zu erfüllen." }
entries[312751] = { ["name"] = "Kralle von Ha-Li", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ha-Lis Brut ist am blauen Himmel Pandarias zu Hause und jagt dort arglose Beute.\"\nBeute von:\nHa-Li\nZone:\nTal der Ewigen Blüten" }
entries[312752] = { ["name"] = "Eiskalt", ["text"] = "20 Meter Reichweite\nSofort\nBewirkt alle 6 Sek. 'Raureif'." }
entries[312753] = { ["name"] = "Hoffnungsvernichtergargon", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Er war einst das treue Reittier eines Lordregenten des Hauses Dornfluch, stellte sich dann aber gegen ihn und sein Gefolge. Mitglieder von Haus Dornfluch munkeln nun über einen im Dunklen lauernden Gargon, der Venthyr auflauert, die sich in die finsteren Bereiche des Kelchdistrikts von Revendreth begeben.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[312754] = { ["name"] = "Kampfgargon Vrednic", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Prinz Renathals treuer Gargon Vrednic begleitet ihn bereits seit Jahrtausenden. In seiner Sinvyrrüstung kann Vrednic allein durch sein Erscheinen alle in Angst und Schrecken versetzen, die ihn mit seinen Reiter in die Schlacht reiten sehen.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[312756] = { ["name"] = "PH Phalynx", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei." }
entries[312758] = { ["name"] = "PH Epic Phalynx", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei." }
entries[312759] = { ["name"] = "Traumlichtrunenhirsch", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Runenhirsche werden jenen gewährt, die der Winterkönigin und dem Hof der Nacht ihre Dienste versichert haben.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[312761] = { ["name"] = "Verzauberter Traumlichtrunenhirsch", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die majestätischen Runenhirsche sind mit ihren kunstvollen Geweihen in der Lage, dem Umgebungslicht des Ardenwalds Anima zu entziehen. Die Anima dient ihnen als Nahrung und verleiht ihnen Geschwindigkeit und Magie.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[312762] = { ["name"] = "Schlundgebundener Seelenjäger", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Seelenjäger werden dazu eingesetzt, Seelen aufzuspüren, die sich vor ihrem dunklen Schicksal in die Einöden flüchten. Sie gehören zu den wenigen Kreaturen, die den Schlund ohne Unbehagen durchqueren.\"\nBeute:\nVollgefressener Schemenhund\nZone:\nDer Schlund" }
entries[312763] = { ["name"] = "Finsterbauhartpanzer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das Chitin des Finsterbauhartpanzers ist robust genug, um Mörsergranaten und Drachenfeuer zu widerstehen. Falls nötig wird es praktischerweise auch alles verzehren, was keine Anima enthält.\"\nAbenteuer:\nShadowlands" }
