entries[312765] = { ["name"] = "Sonnentänzer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser sonnengebadete Renner galoppiert sorgenfrei auf Lichtstrahlen.\"\nBeute:\nZone:\nBastion" }
