entries[312771] = { ["name"] = "Symbiotische Präsenz", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr 20 Sek. lang 22 Hauptwert .\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
