entries[312773] = { ["name"] = "Symbiotische Präsenz", ["text"] = "40 Meter Reichweite\nDer Bonus auf Hauptwert ist um 25% erhöht." }
entries[312774] = { ["name"] = "Symbiotische Präsenz", ["text"] = "40 Meter Reichweite\nWenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhalten Ihr und der Verbündete 20 Sek. lang 18 Tempo.\n\nEs kann immer nur ein Verbündeter diesen Tempoeffekt haben." }
