entries[312776] = { ["name"] = "Zirpende Animilbe", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese außergewöhnlich wendigen Flieger sind ausgezeichnete Reittiere, sobald man ihnen beigebracht hat, ihren Reitern nicht ihre gesamte Anima zu entziehen.\"\nAbenteuer:\nShadowlands" }
entries[312777] = { ["name"] = "Silberspitzenfledderschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese von Prinz Renathal von Revendreth gezüchteten seltenen Fledderschwingen sind äußerst loyal und lassen nur jene an sich heran, die vom Prinzen selbst als würdig erachtet werden.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords" }
