entries[312922] = { ["name"] = "Überlebenswille", ["text"] = "Sofort\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 30% länger an . Dieser Effekt kann nur ein Mal alle 1.5 Min. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[312923] = { ["name"] = "Kampfanalyse", ["text"] = "Kampfanalyse Mechagnome Volksfähigkeit\nIhr sammelt und analysiert alle 5 Sek. Kampfdaten, wodurch sich Euer Primärwert um 153 erhöht. Bis zu 10-mal stapelbar. Außerhalb des Kampfes verfallen die Daten langsam." }
