entries[313307] = { ["name"] = "Fragment des Verstandes", ["text"] = "Unbegrenzte Reichweite\nSofort\nLässt eine Kugel der geistigen Gesundheit in der Nähe entstehen, die 15 Sek. lang bestehen bleibt. Stellt bei einem Spielercharakter bei Kontakt 5 geistige Gesundheit wieder her." }
entries[313308] = { ["name"] = "Seuchenbombe tragen" }
entries[313309] = { ["name"] = "Fressen", ["text"] = "Wirken in 1 sek. 6 sek. Abklingzeit\nFügt einem Gegner mit wilden Bissen körperlichen Schaden zu." }
entries[313310] = { ["name"] = "Resonanz der Weltader", ["text"] = "Sofort\nKonzentriert Energie in das Herz von Azeroth und lässt 2 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 12 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 8 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren." }
entries[313311] = { ["name"] = "Hinterlistiger Schlag", ["text"] = "Nahkampfreichweite\nSofort\nSchlägt das Ziel nieder und betäubt es für 2 Sek." }
